
/* ================= FORM BUILDER ================= */
const FT_={short:['Short text','text'],long:['Long text','note'],email:['Email','mail'],phone:['Phone','phone'],choice:['Multiple choice','mywork'],check:['Checkboxes','check'],drop:['Dropdown','down'],date:['Date','cal'],file:['File upload','upload'],rate:['Rating','star'],head:['Section heading','h1']};
const FB={sel:0,dev:'phone',fields:[['head','Tell us about your business',''],['short','Business name','',1],['long','What do you sell?','In one or two sentences',1],['choice','Who is your best client?','',1,['Busy professionals','Parents','Students']],['email','Best email for updates','',1],['file','Upload your logo','PNG or SVG',0],['rate','How clear is your brand today?','',0]]};
const FORMS=[['bb','Brand Base form','Published',12,'Clients · Brand Base'],['quiz','Fitness quiz','Draft',0,'Harry Kaye quiz funnel'],['apply','Coaching application','Published',41,'Website'],['fb','Client feedback','Draft',0,'—']];
const fieldHTML=(f,i,ed)=>{const[t,l,h,req,opts]=f;const ctl=t==='head'?'':t==='choice'||t==='check'?`<div class="opts">${(opts||['Option 1','Option 2']).map(o=>`<span><i style="${t==='check'?'border-radius:5px':''}"></i>${o}</span>`).join('')}</div>`:t==='rate'?`<div style="display:flex;gap:4px;color:#E6A700">${ic('star',26).repeat(5)}</div>`:t==='file'?`<div class="ctl" style="border-style:dashed;justify-content:center;min-height:64px">${ic('upload',18)}&nbsp;Drop a file or browse</div>`:`<div class="ctl" style="${t==='long'?'min-height:88px;align-items:flex-start;padding-top:12px':''}">${t==='drop'?'Choose…':t==='date'?'DD / MM / YYYY':''}</div>`;
return t==='head'?`<div ${ed?'role="button" tabindex="0"':''} class="fq" ${ed?`aria-pressed="${FB.sel===i}" data-act="fsel:${i}"`:''}><h3 class="h2" style="font-size:22px">${l}</h3>${ed?tools(i):''}</div>`:`<${ed?'div role="button" tabindex="0"':'div'} class="fq" ${ed?`aria-pressed="${FB.sel===i}" data-act="fsel:${i}"`:''}><label>${l}${req?' <span style="color:var(--danger)">*</span>':''}</label>${h?`<small class="muted">${h}</small>`:''}${ctl}${ed?tools(i):''}</div>`};
const tools=i=>`<span class="tools"><button data-act="fmv:${i}|-1" aria-label="Move up">${ic('right',16).replace('<svg','<svg style="transform:rotate(-90deg)"')}</button><button data-act="fmv:${i}|1" aria-label="Move down">${ic('right',16).replace('<svg','<svg style="transform:rotate(90deg)"')}</button><button data-act="fdup:${i}" aria-label="Duplicate">${ic('copy',16)}</button><button data-act="fdel:${i}" aria-label="Delete">${ic('trash',16)}</button></span>`;
function fbuilder(){const f=FB.fields[FB.sel]||FB.fields[0];return `<div class="builder"><div><p class="over" style="margin:0 0 8px 4px">Add a field</p><div class="palette">${Object.entries(FT_).map(([k,[l,i]])=>`<button data-act="fadd:${k}">${ic(i,18)}${l}</button>`).join('')}</div></div>
<div class="fcanvas" id="fcanvas">${FB.fields.map((x,i)=>fieldHTML(x,i,1)).join('')}<button class="addrow" style="justify-content:center;border:1.5px dashed var(--line2);border-radius:14px" data-act="fadd:short">${ic('plus',18)}Add question</button></div>
<aside class="propbox"><p class="sec-t" style="margin-top:0">${ic('sliders',16)}${FT_[f[0]][0]}</p><div class="field"><label for="fl">Question</label><input id="fl" value="${esc(f[1])}" data-fi="${FB.sel}"></div><div class="field"><label for="fh">Help text</label><input id="fh" value="${esc(f[2]||'')}" placeholder="Optional"></div>${f[0]==='head'?'':`<div class="tg-row">Required<button class="toggle" role="switch" aria-checked="${!!f[3]}" aria-label="Required" data-act="freq"></button></div>`}${f[4]?`<p class="sec-t">Options</p>${f[4].map(o=>`<div class="inp" style="margin-bottom:6px"><input value="${o}" aria-label="Option"></div>`).join('')}<button class="linkbtn" data-act="noop">+ Add option</button>`:''}<p class="sec-t">${ic('gantt',16)}Logic</p><button class="chip" data-act="toast:Show this question only when an earlier answer matches.">Show if…</button></aside></div>`}
function openFormOverlay(ctx){const d=document.createElement('div');d.className='overlay-page';d.id='fov';d.innerHTML=`<div class="ov-top"><button class="iconbtn" data-act="fovx" aria-label="Back to ${ctx}">${ic('right',20).replace('<svg','<svg style="transform:scaleX(-1)"')}</button>${plate(app('forms'),32)}<div class="grow"><b>Extra questions: pricing</b><small>Inside ${ctx} › Brand Base · you won’t leave Clients</small></div><span class="savest dirty" id="fsave"><i></i>Unsaved</span><button class="btn ghost sm hide-m" data-act="fovx">Cancel</button><button class="btn primary sm" data-act="fovsave">Save form</button></div><div class="content" style="max-width:none" id="fovb">${fbuilder()}</div>`;document.body.append(d);d.querySelector('button').focus()}
const FNAV=[['forms/list','Forms','forms'],['forms/subs','Responses','inbox',3],['forms/tpl','Templates','copy']];
VIEWS.forms=p=>{const pg=p[0]||'list';
if(pg==='list')return shell('forms',{nav:FNAV,cur:'forms/list',body:`${head('Forms','Forms, quizzes and intake. Built once, reused anywhere.',`<button class="btn primary" data-act="nav:forms/b/quiz">${ic('plus',18,'',2.2)}New form</button>`)}<div class="tblwrap"><table class="tbl"><thead><tr><th>Form</th><th>Status</th><th>Responses</th><th>Used in</th></tr></thead><tbody>${FORMS.map(([id,n,s,r,u])=>`<tr><td class="t1"><button class="fname" data-act="nav:forms/b/${id}">${ic('forms')}${n}</button></td><td data-l="Status"><span class="pill ${s==='Published'?'blue':''}">${s}</span></td><td data-l="Responses">${r}</td><td data-l="Used in">${u}</td></tr>`).join('')}</tbody></table></div>`});
if(pg==='subs')return shell('forms',{nav:FNAV,cur:'forms/subs',body:`${head('Responses','Brand Base form · 12 responses. Summary first, then each answer.',`<select class="sel"><option>Brand Base form</option><option>Coaching application</option></select>`)}<div class="kpis">${[['12','Responses'],['83%','Completion'],['4 min','Median time'],['3','New this week']].map(([b,x])=>`<div><b>${b}</b><span>${x}</span></div>`).join('')}</div><div class="grid2" style="margin:18px 0"><section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">Who is your best client?</p>${[['Busy professionals',58],['Parents',25],['Students',17]].map(([l,v])=>`<div class="ws-bar"><span class="nm" style="width:150px">${l}</span><span class="prog" style="--v:${v}%"><i style="background:#F07C1A"></i></span><span class="mono">${v}%</span></div>`).join('')}</section><section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">How clear is your brand today?</p><div class="spark">${[1,2,5,3,1].map(v=>`<i style="--v:${v*18}px"></i>`).join('')}</div><small class="muted">1 to 5 stars · average 2.8</small></section></div>${head('All answers','Personal data stays here unless you export it.',`<button class="btn ghost" aria-disabled="true" data-act="toast:Export needs the backend and permission.">${ic('download',18)}Export</button>`)}<div class="tblwrap"><table class="tbl"><thead><tr><th>Person</th><th>Form</th><th>Submitted</th><th></th></tr></thead><tbody>${[['Harry Kaye','Brand Base form','2 Oct'],['Elena Ruiz','Brand Base form','Yesterday'],['Ali Hassan','Coaching application','Today']].map(([n,f,d])=>`<tr><td class="t1">${n}</td><td data-l="Form">${f}</td><td data-l="Submitted">${d}</td><td data-l=""><button class="btn ghost sm" data-act="toast:Opens the full response.">View</button></td></tr>`).join('')}</tbody></table></div>`});
if(pg==='tpl')return shell('forms',{nav:FNAV,cur:'forms/tpl',body:`${head('Templates','Start from a proven form.')}<div class="cardgrid">${['Brand Base','Fitness quiz','Application','Feedback','Event sign-up'].map(n=>`<button class="card" data-act="nav:forms/b/quiz"><span class="wic" style="--c:#F07C1A">${ic('forms',22)}</span><h3>${n}</h3><p>Ready to edit.</p></button>`).join('')}</div>`});
const id=p[1]||'quiz',fm=FORMS.find(x=>x[0]===id)||FORMS[1];const mode=pg==='p'?'preview':'build';
return shell('forms',{nav:FNAV,cur:'forms/list',crumbs:[['Forms'],[fm[1]]],body:`<div class="toolbar"><h1 class="h2" style="font-size:24px">${fm[1]}</h1><span class="pill ${fm[2]==='Published'?'blue':''}">${fm[2]}</span><span class="grow"></span>${vsw([['build','Build','edit'],['preview','Preview','eye']],mode,'fmode')}<button class="btn ghost" data-act="fpub">${ic('send',18)}Publish</button></div>${mode==='build'?fbuilder():`<div style="display:flex;justify-content:center;margin-bottom:14px">${vsw([['phone','Phone','phone'],['desk','Desktop','desk']],FB.dev,'fdev')}</div><div class="device ${FB.dev}"><div class="scr"><div style="display:grid;gap:6px">${FB.fields.map((x,i)=>fieldHTML(x,i,0)).join('')}<button class="btn primary full" data-act="toast:Preview: answers are not saved.">Submit</button></div></div></div>`}`})};
Object.assign(ACT,{
fsel:v=>{FB.sel=+v;rfb()},fadd:k=>{FB.fields.push([k,'New '+FT_[k][0].toLowerCase()+' question','',0,k==='choice'||k==='check'||k==='drop'?['Option 1','Option 2']:undefined]);FB.sel=FB.fields.length-1;rfb();setTimeout(()=>{$('#fl')?.select();$('#fcanvas [aria-pressed="true"]')?.scrollIntoView({block:'center',behavior:reduce?'auto':'smooth'})},30)},
fmv:v=>{const[i,d]=v.split('|').map(Number),j=i+d;if(j<0||j>=FB.fields.length)return;[FB.fields[i],FB.fields[j]]=[FB.fields[j],FB.fields[i]];FB.sel=j;rfb()},
fdup:v=>{FB.fields.splice(+v+1,0,[...FB.fields[+v]]);FB.sel=+v+1;rfb()},fdel:v=>{FB.fields.splice(+v,1);FB.sel=Math.max(0,+v-1);rfb();toast('Question removed.')},
freq:(v,t)=>{const f=FB.fields[FB.sel];f[3]=!f[3];rfb()},fmode:v=>nav(`forms/${v==='preview'?'p':'b'}/${RT.p[1]||'quiz'}`,true),fdev:v=>{FB.dev=v;draw()},
fpub:()=>dlg({title:'Publish form',body:`<div style="display:grid;gap:2px;margin:10px 0">${[['Share link',1],['Embed on a website',0],['Send answers to a client record',1]].map(([l,on])=>`<div class="tg-row">${l}<button class="toggle" role="switch" aria-checked="${!!on}" data-act="tgl" aria-label="${l}"></button></div>`).join('')}</div><p class="hint">Spam protection and data retention follow your organization’s rules.</p>`,acts:[['Cancel','noop'],['Publish','toast:Publishing needs the backend. Saved as ready.:ok','primary']]}),
fovx:()=>{if($('#fsave')?.classList.contains('dirty'))dlg({title:'Leave without saving?',body:'Your form changes aren’t saved.',acts:[['Keep editing','noop'],['Discard','fovclose','ghost'],['Save and leave','fovsave','primary']]});else ACT.fovclose()},
fovclose:()=>$('#fov')?.remove(),fovsave:()=>{$('#fov')?.remove();toast('Form saved to Brand Base. It’s prepared, not sent.','ok')}
});
function rfb(){const host=$('#fovb')||$('.content');if($('#fovb'))$('#fovb').innerHTML=fbuilder();else draw()}
INPUT.fl=e=>{FB.fields[+e.dataset.fi][1]=e.value;const q=$$('#fcanvas .fq')[+e.dataset.fi];const lb=q?.querySelector('label,h3');if(lb)lb.firstChild.textContent=e.value;$('#fsave')?.classList.add('dirty')};

