const LAD=[['Free quiz','Lead magnet','Free','Find out what’s holding your fitness back.','#5FDCCB',.32],['7-day kickstart','Front-end offer','$27','A week of guided workouts.','#FFD45E',.45],['12-week coaching','Core offer','$497','Coaching, plan and weekly check-ins.','#FF9A7E',.62],['Nutrition add-on','Upsell','$97/mo','Meal plans and macros.','#A898FF',.78],['VIP 1:1','High-ticket','$2,000','Private coaching with Harry.','#2B63F6',.96]];
