VIEWS.ladder=p=>{const pg=p[0]||'list';
if(pg==='list')return shell('ladder',{nav:VNAV,cur:'ladder/list',body:`${head('Value Ladders','Map how customers climb from free to premium.',`<button class="btn primary" data-act="nav:ladder/map/hk">${ic('plus',18,'',2.2)}New ladder</button>`)}<div class="cardgrid">${[['hk','Harry Kaye PT ladder','5 steps · Clients'],['l2f','L2F agency ladder','4 steps · Office']].map(([id,n,m])=>`<button class="card" data-act="nav:ladder/map/${id}"><div style="display:flex;align-items:flex-end;gap:5px;height:70px">${LAD.map(s=>`<i style="flex:1;height:${s[5]*100}%;border-radius:6px 6px 2px 2px;background:${s[4]}"></i>`).join('')}</div><h3>${n}</h3><div class="foot">${m}</div></button>`).join('')}</div>`});
if(pg==='history')return shell('ladder',{nav:VNAV,cur:'ladder/history',body:`${head('History','Changes to step order and linked offers.')}<section class="panel" style="padding:20px">${[['UM','moved “Nutrition add-on” above “12-week coaching”','Today'],['TR','linked “VIP 1:1” to Offers & Products','Monday']].map(([a,t,w])=>`<div class="comment">${av(a)}<div><p>${PEOPLE[a][0]} ${t}</p><small>${w}</small></div></div>`).join('')}</section>`});
return shell('ladder',{nav:VNAV,cur:'ladder/list',crumbs:[['Value Ladder'],['Harry Kaye PT ladder']],body:`${head('Harry Kaye PT ladder','Each step links to a real offer. Changing the ladder never changes the offer or its price.',`<button class="btn ghost" data-act="toast:Add a step and link an offer.">${ic('plus',18)}Add step</button>`)}<div class="lad-model">${[['1,000','Visitors a month'],['30%','take the free quiz'],['8%','buy the $27 kickstart'],['25%','join coaching'],['$11,180','Revenue a month']].map(([b,s],i)=>`<div class="${i===4?'tot':''}"><b>${b}</b><span>${s}</span></div>`).join(`<span class="lm-ar">${ic('arrow',16)}</span>`)}</div><p class="hint" style="margin:-6px 0 14px">Change any rate to see the effect. Conversion rates can come from Funnel Mapper Pro forecasts once linked.</p><div class="panel" style="padding:10px 18px 18px;overflow:hidden"><div class="ladder"><span class="ladder-arrow"></span>${LAD.map((s,i)=>`<button class="step" style="--c:${s[4]};--h:${Math.round(s[5]*440)}px;--i:${i}" data-act="lstep:${i}"><span class="lv">${i+1} · ${s[1]}</span><b>${s[0]}</b><small>${s[3]}</small><span class="price">${s[2]}</span></button>`).join('')}</div></div>`})};
ACT.lstep=v=>{const s=LAD[+v];$$('.step').forEach((b,i)=>b.setAttribute('aria-pressed',i===+v));openDrawer(`<div class="drw-h"><span class="pill">Step ${+v+1} · ${s[1]}</span><span class="grow"></span><button class="iconbtn" data-act="drawerx" aria-label="Close">${ic('x')}</button></div><h2 class="drw-title">${s[0]}</h2><p class="tx2">${s[3]}</p><div class="sec-t">${ic('link',16)}Linked offer</div>${+v===3?`<div class="notice danger">${ic('alert',18)}<span>The linked offer was archived. Pick another, or keep this step as a gap.</span></div>`:`<div class="linkrow" style="background:var(--sunk)">${ic('offer')}<span class="main"><b>${s[0]}</b><small>Offers & Products · ${s[2]}</small></span><span class="pill blue">Linked</span></div>`}<div class="sec-t">Audience and value</div><dl class="kv2"><dt>For</dt><dd>Busy mums getting back to fitness</dd><dt>Why next</dt><dd>Natural step after ${+v?LAD[+v-1][0]:'first visit'}</dd><dt>Owner</dt><dd>${av('UM')} Usman</dd></dl><div class="sec-t">Assumptions</div><p class="tx2">About 20% move up to this step.</p>`)};

