VIEWS.whiteboard=p=>{const pg=p[0]||'home';
if(pg==='home')return shell('whiteboard',{nav:[['whiteboard/home','Boards','whiteboard'],['whiteboard/tpl','Templates','copy']],cur:'whiteboard/home',body:`${head('Whiteboards',`Shared boards for ${oname()}. Project boards stay in Projects.`,`<button class="btn primary" data-act="nav:whiteboard/board/new">${ic('plus',18,'',2.2)}New board</button>`)}<p class="over" style="margin-bottom:10px">Start from a template</p><div class="cardgrid" style="margin-bottom:26px;grid-template-columns:repeat(auto-fill,minmax(170px,1fr))">${[['Blank','#7C818D'],['Funnel flow','#2B63F6'],['Brainstorm','#FFC633'],['Retro','#E9488F'],['Mind map','#13A592']].map(([n,c])=>`<button class="card" data-act="nav:whiteboard/board/new" style="padding:14px"><span style="height:80px;border-radius:12px;background:radial-gradient(var(--line2) 1px,transparent 1px) 0 0/12px 12px,color-mix(in srgb,${c} 14%,var(--surface2))"></span><b>${n}</b></button>`).join('')}</div><p class="over" style="margin-bottom:10px">Recent boards</p><div class="cardgrid">${[['Quiz funnel flow','Edited 10 min ago',1],['Q4 content ideas','Yesterday',0],['Team retro, October','Last week',1]].map(([n,m,s])=>`<button class="card" data-act="nav:whiteboard/board/b1"><span style="height:140px;border-radius:14px;position:relative;background:radial-gradient(var(--line2) 1px,transparent 1px) 0 0/14px 14px,var(--surface2);overflow:hidden">${['#FFE58F','#FFC2D8','#BDE8DF','#C9D8FF'].map((c,i)=>`<i style="position:absolute;left:${10+i*22}%;top:${20+(i%2)*30}%;width:18%;height:30%;background:${c};border-radius:3px;transform:rotate(${i%2?2:-2}deg)"></i>`).join('')}</span><h3>${n}${s?' '+ic('star',14).replace('fill="none"','fill="#E6A700" stroke="#E6A700"'):''}</h3><div class="foot">${avs(['TR','AR'])}${m}</div></button>`).join('')}</div>`});
if(pg==='tpl')return shell('whiteboard',{nav:[['whiteboard/home','Boards','whiteboard'],['whiteboard/tpl','Templates','copy']],cur:'whiteboard/tpl',body:head('Templates','Approved templates for your team.')+`<p class="hint">Owners and admins can save any board as a template.</p>`});
const T=[['cursor','Select (V)'],['hand','Pan (H)'],['sticky','Sticky note (S)'],['text','Text (T)'],['shape','Shape (R)'],['pen','Pen (P)'],['frame','Frame (F)'],['arrow','Connector (L)']];
return `${focusBar('whiteboard',{title:'<b>Quiz funnel flow</b>',sub:oname()+' · Harry Kaye quiz funnel',back:'whiteboard/home',right:''}).replace('</header>','')}<span class="savest hide-m"><i></i>Saved</span><button class="iconbtn hide-m" aria-label="Undo" data-act="noop">${ic('undo')}</button><button class="iconbtn hide-m" aria-label="Redo" data-act="noop">${ic('redo')}</button><span class="wb-presence hide-m">${avs(['TR','AR','SN'])}</span><button class="iconbtn" aria-label="Comments" data-act="toast:Comments and @mentions open here.">${ic('msg')}</button><button class="btn ghost sm hide-m" data-act="toast:Presents frames in order.">${ic('play',16)}Present</button><button class="iconbtn hide-m" aria-label="Export" data-act="toast:Export as PNG, SVG or PDF.">${ic('download',18)}</button><button class="btn primary sm" data-act="toast:Share opens board roles: viewer, commenter, editor.">${ic('share',16)}Share</button></header>
<div class="wb" id="wb"><div class="wb-tools" role="toolbar" aria-label="Board tools">${T.map(([k,l])=>`<button aria-label="${l}" title="${l}" aria-pressed="${WB.tool===k}" data-act="wtool:${k}">${ic(k,20)}</button>`).join('')}</div><div class="wb-world" id="wbw">${wbItems()}</div>
<div class="wb-mini" aria-hidden="true">${WB.items.map(i=>`<i style="left:${i.x/7}px;top:${i.y/7}px;width:${(i.w||180)/7}px;height:${(i.h||160)/7}px;--c:${i.t==='frame'?'transparent':i.c};${i.t==='frame'?'border:1px dashed var(--line2)':''}"></i>`).join('')}<span class="vp" style="left:4px;top:4px;width:110px;height:70px"></span></div>
<div class="wb-zoom"><button aria-label="Zoom out" data-act="wz:-1">${ic('zout',18)}</button><span id="wzl" style="min-width:52px;text-align:center">${Math.round(WB.z*100)}%</span><button aria-label="Zoom in" data-act="wz:1">${ic('zin',18)}</button><button aria-label="Fit" data-act="wz:0">${ic('target',18)}</button></div></div>`};
function wbItems(){return WB.items.map((i,k)=>i.t==='frame'?`<div class="wframe" style="left:${i.x}px;top:${i.y}px;width:${i.w}px;height:${i.h}px"><span>${i.l}</span></div>`:i.t==='shape'?`<div class="wshape sticky" data-k="${k}" style="left:${i.x}px;top:${i.y}px;width:${i.w}px;min-height:${i.h}px;background:color-mix(in srgb,${i.c} 14%,var(--surface));border:2px solid ${i.c};border-radius:18px;color:var(--text);--r:0deg;display:grid;place-items:center">${i.l}</div>`:`<div class="sticky" data-k="${k}" style="left:${i.x}px;top:${i.y}px;--c:${i.c};--r:${i.r}deg" ${''}><span contenteditable="true" spellcheck="false">${i.x2}</span><small>${['Tabish','Ayesha','Sana'][k%3]}</small></div>`).join('')}
AFTER.whiteboard=()=>wbApply();
function wbApply(){const w=$('#wbw');if(w)w.style.transform=`translate(${WB.x}px,${WB.y}px) scale(${WB.z})`;const l=$('#wzl');if(l)l.textContent=Math.round(WB.z*100)+'%'}
Object.assign(ACT,{wtool:v=>{WB.tool=v;$$('.wb-tools button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.act==='wtool:'+v));if(v==='sticky')toast('Click the board to add a sticky note.')},
wz:v=>{WB.z=+v===0?.9:Math.min(2,Math.max(.3,WB.z+(+v)*.15));if(+v===0){WB.x=40;WB.y=10}wbApply()}});
let wdrag=null;
document.addEventListener('pointerdown',e=>{const b=e.target.closest?.('#wb');if(!b||e.target.closest('.wb-tools,.wb-zoom,.wb-mini'))return;const s=e.target.closest('.sticky');
 if(WB.tool==='sticky'&&!s){const r=b.getBoundingClientRect();WB.items.push({t:'s',x:(e.clientX-r.left-WB.x)/WB.z-90,y:(e.clientY-r.top-WB.y)/WB.z-60,c:['#FFE58F','#FFC2D8','#BDE8DF','#C9D8FF'][WB.items.length%4],x2:'New idea',r:(Math.random()-.5)*4});$('#wbw').innerHTML=wbItems();WB.tool='cursor';ACT.wtool('cursor');return}
 if(s&&WB.tool==='cursor'){if(e.target.isContentEditable&&e.detail>1)return;const k=+s.dataset.k;wdrag={k,el:s,sx:e.clientX,sy:e.clientY,ox:WB.items[k].x,oy:WB.items[k].y};s.classList.add('drag');s.setPointerCapture?.(e.pointerId)}
 else{wdrag={pan:1,sx:e.clientX,sy:e.clientY,ox:WB.x,oy:WB.y};b.style.cursor='grabbing'}});
document.addEventListener('pointermove',e=>{if(!wdrag)return;const dx=e.clientX-wdrag.sx,dy=e.clientY-wdrag.sy;if(wdrag.pan){WB.x=wdrag.ox+dx;WB.y=wdrag.oy+dy;wbApply()}else{const it=WB.items[wdrag.k];it.x=wdrag.ox+dx/WB.z;it.y=wdrag.oy+dy/WB.z;wdrag.el.style.left=it.x+'px';wdrag.el.style.top=it.y+'px'}});
document.addEventListener('pointerup',()=>{if(!wdrag)return;wdrag.el?.classList.remove('drag');$('#wb')&&($('#wb').style.cursor='');wdrag=null});
document.addEventListener('wheel',e=>{if(!e.target.closest?.('#wb'))return;e.preventDefault();if(e.ctrlKey||e.metaKey){WB.z=Math.min(2,Math.max(.3,WB.z-e.deltaY*.002))}else{WB.x-=e.deltaX;WB.y-=e.deltaY}wbApply()},{passive:false});

/* ================= SOCIAL PLANNER ================= */
const CH={ig:['Instagram','#E9488F','IG'],li:['LinkedIn','#0F6CBD','in'],yt:['YouTube','#E5482F','YT'],fb:['Facebook','#2B5CF0','f']};
const POSTS=[[1,'ig','Quiz is live: find your fitness type','Scheduled'],[3,'li','Case study: 41 booked calls','In review'],[3,'ig','3 myths about funnels','Draft'],[6,'yt','Funnel teardown #4','Scheduled'],[8,'ig','Client win: Sarah','Approved'],[10,'li','Why we promise 30 days of fixes','Draft'],[14,'fb','Webinar reminder','Scheduled'],[-3,'ig','Behind the scenes','Published'],[-1,'li','October offer','Published']];
const PSC={Scheduled:'blue',Approved:'blue','In review':'warn',Draft:'',Published:'brand',Failed:'danger'};
const SNAV=[['social/calendar','Calendar','cal'],['social/board','Pipeline','board'],['social/posts','Posts','note'],['social/campaigns','Campaigns','flag'],['social/queue','Queue','list'],['social/approvals','Approvals','check',1],['social/channels','Channels','plug']];
const sShell=(cur,body)=>shell('social',{nav:SNAV,cur,body});
VIEWS.social=p=>{const pg=p[0]||'calendar';
if(pg==='calendar')return sShell('social/calendar',`${head('Calendar','Planned and scheduled posts for '+oname()+'.',`<button class="btn primary" data-act="compose">${ic('plus',18,'',2.2)}New post</button>`)}<div class="notice plain" style="margin-bottom:14px">${ic('plug',18)}<span>Publishing stays in GoHighLevel. Plan, write and approve here, then send approved posts to GHL in one step. Analytics come back from GHL later.</span></div><div class="toolbar"><b style="font:700 20px/1 var(--font-d)">October 2026</b><span class="grow"></span>${Object.values(CH).map(([n,c])=>`<span class="tag"><span class="dotc" style="--c:${c};width:8px;height:8px;margin-right:6px"></span>${n}</span>`).join('')}</div><div class="cal">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dh">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const o=i-21,d=dOf(o);return `<div class="dc ${d.getMonth()!==9?'out':''} ${o===3?'today':''}"><span class="dn">${d.getDate()}</span>${POSTS.filter(x=>x[0]===o).map(x=>`<button class="ev" style="--c:${CH[x[1]][1]}" data-act="compose:${POSTS.indexOf(x)}">${CH[x[1]][2]} · ${x[2]}</button>`).join('')}</div>`}).join('')}</div>`);
if(pg==='posts'||pg==='queue'||pg==='approvals'){const L=pg==='approvals'?POSTS.filter(x=>x[3]==='In review'):pg==='queue'?POSTS.filter(x=>x[3]==='Scheduled'):POSTS;return sShell('social/'+pg,`${head({posts:'Posts',queue:'Queue',approvals:'Approvals'}[pg],{posts:'Drafts and versions for every channel.',queue:'What will publish, in order. Nothing publishes without approval.',approvals:'Posts waiting for a reviewer.'}[pg],`<button class="btn primary" data-act="compose">${ic('plus',18,'',2.2)}New post</button>`)}<div class="tblwrap"><table class="tbl"><thead><tr><th>Post</th><th>Channel</th><th>Date</th><th>Status</th></tr></thead><tbody>${L.map(x=>`<tr><td class="t1"><button class="fname" data-act="compose:${POSTS.indexOf(x)}">${ic('note')}${x[2]}</button></td><td data-l="Channel"><span class="tag" style="background:color-mix(in srgb,${CH[x[1]][1]} 16%,var(--surface));color:${CH[x[1]][1]}">${CH[x[1]][0]}</span></td><td data-l="Date">${dl(x[0])}</td><td data-l="Status"><span class="pill ${PSC[x[3]]}">${x[3]}</span></td></tr>`).join('')}</tbody></table></div>`)}
if(pg==='board')return sShell('social/board',`${head('Pipeline','Every post from idea to posted. Publishing happens in GoHighLevel; this is where you plan, write and approve.')}<div class="kanban">${['Idea','Draft','In review','Approved','Scheduled in GHL','Posted'].map((c,i)=>`<div class="kcol"><div class="kcol-h"><b>${c}</b><span class="muted mono">${[3,2,1,1,2,4][i]}</span></div>${POSTS.slice(i,i+[2,2,1,1,2,2][i]).map(x=>`<button class="kcard" data-act="compose:${POSTS.indexOf(x)}"><span class="tag" style="color:${CH[x[1]][1]}">${CH[x[1]][0]}</span><b>${x[2]}</b><span class="foot">${dl(x[0])}</span></button>`).join('')}${i===3?`<button class="addrow" data-act="toast:Exports approved posts as a CSV that GoHighLevel’s Social Planner imports.">${ic('download',16)}Send approved to GHL</button>`:''}</div>`).join('')}</div>`);
if(pg==='campaigns')return sShell('social/campaigns',`${head('Campaigns','Group posts around a launch or theme and track posted vs planned.')}<div class="cardgrid">${[['Funnel Challenge launch','Active',12,20],['Case study month','Planned',0,8]].map(([n,s,a,b])=>`<div class="card"><span class="pill ${s==='Active'?'blue':''}" style="justify-self:start">${s}</span><h3>${n}</h3><span class="prog" style="--v:${a/b*100}%"><i></i></span><div class="foot">${a} of ${b} posted</div></div>`).join('')}</div>`);
if(pg==='channels')return sShell('social/channels',`${head('Channels','Connected accounts. Managed by admins and channel owners.')}<div class="cardgrid">${Object.values(CH).map(([n,c,l])=>`<div class="card"><div class="integ"><span class="lg" style="--c:${c}">${l}</span><div><h3>${n}</h3><small class="muted">Not connected</small></div></div><button class="btn ghost sm" aria-disabled="true" data-act="toast:Connecting needs the provider review and the backend.">Connect</button></div>`).join('')}</div>`);
return sShell('social/calendar','')};
ACT.compose=v=>{const x=POSTS[+v]||[5,'ig','','Draft'];openDrawer(`<div class="drw-h"><b class="grow" style="font:700 20px/1 var(--font-d)">${v?'Edit post':'New post'}</b><button class="iconbtn" data-act="drawerx" aria-label="Close">${ic('x')}</button></div><p class="sec-t" style="margin-top:4px">Channels</p><div style="display:flex;gap:6px;flex-wrap:wrap">${Object.entries(CH).map(([k,[n,c]])=>`<button class="chip" aria-pressed="${k===x[1]}" style="${k===x[1]?`border-color:${c};color:${c};background:color-mix(in srgb,${c} 10%,var(--surface))`:''}" data-act="tgl">${n}</button>`).join('')}</div><div class="field" style="margin-top:14px"><label for="pt">Post text</label><textarea id="pt">${x[2]}</textarea></div><button class="chip" data-act="toast:Pick an image from Drive. It’s linked, not copied.">${ic('imgI',16)}Add media from Drive</button><p class="sec-t">Preview</p><div class="panel" style="padding:14px;display:grid;gap:10px"><div style="display:flex;gap:10px;align-items:center">${mark(org(),32)}<b style="font-size:14px">${oname()}</b><small class="muted">· ${CH[x[1]][0]}</small></div><p style="font-size:14px">${x[2]||'Your post text appears here.'}</p><span style="aspect-ratio:1;border-radius:12px;background:radial-gradient(60% 70% at 30% 30%,#9C8BFF,transparent),radial-gradient(60% 70% at 80% 70%,#FF8A6B,transparent),#2B2050"></span></div><div class="row2" style="margin-top:14px"><div class="field"><label for="pd">Date</label><input id="pd" value="${dOf(x[0]).toLocaleDateString('en-GB')}"></div><div class="field"><label for="ptm">Time</label><input id="ptm" value="18:30"></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" data-act="toast:Sent for review.:ok">Submit for review</button><button class="btn ghost" data-act="toast:Draft saved.:ok">Save draft</button></div>`)};
